import { join } from "path"
import { fileURLToPath } from "url"

const MODEL_BASE64: string = ""

export async function getModelBuffer(): Promise<Uint8Array | null> {
  if (MODEL_BASE64.length > 1000) {
    try {
      const buffer = Buffer.from(MODEL_BASE64, "base64")
      console.log(`[INFO] Loaded embedded model: ${buffer.length} bytes`)
      return new Uint8Array(buffer)
    } catch (error) {
      console.log("[DEBUG] Failed to load embedded model:", error)
    }
  }

  const possiblePaths = [
    join(process.env.HOME || "/tmp", ".opencode", "wakeword_models", "hey_jarvis_v0.1.onnx"),
    join(__dirname, "hey_jarvis_v0.1.onnx"),
    join(process.cwd(), "src", "wake-word", "hey_jarvis_v0.1.onnx"),
    join(fileURLToPath(import.meta.url), "..", "hey_jarvis_v0.1.onnx"),
    "/opt/inference/opencode/packages/opencode/src/wake-word/hey_jarvis_v0.1.onnx",
  ]

  for (const modelPath of possiblePaths) {
    try {
      const file = Bun.file(modelPath)
      const exists = await file.exists()
      if (!exists) {
        console.log(`[DEBUG] Model not found at: ${modelPath}`)
        continue
      }

      const buffer = await file.arrayBuffer()
      console.log(`[INFO] Loaded model from file: ${modelPath} (${buffer.byteLength} bytes)`)
      return new Uint8Array(buffer)
    } catch (error) {
      console.log(`[DEBUG] Failed to load model from ${modelPath}:`, error)
      continue
    }
  }

  console.error("[ERROR] Could not load wake word model from any location")
  return null
}
